import React, { useRef, useState, createRef, WheelEvent, useCallback } from 'react';
import type { ProjectSlide } from './slide';
import CarouselArrow from './carouselArrow';
import CarouselIndex from './carouselIndex';

interface VerticalCarouselProps {
    slides: ProjectSlide[];
}

const VerticalCarousel: React.FC<VerticalCarouselProps> = ({ slides }) => {
    const [activeSlideIndex, setActiveSlideIndex] = useState(0);
    const [slideCount] = useState(slides.length);
    const slideRefs = useRef(slides.map(() => createRef<HTMLDivElement>()));
    const [isScrolling, setIsScrolling] = useState(false);
    const lastScrollTime = useRef(Date.now());

    const handleScroll = useCallback((event: React.UIEvent<HTMLDivElement, UIEvent>) => {
        const currentScroll = event.currentTarget.scrollTop;
        const slideHeight = window.innerHeight;
        const nextSlideIndex = Math.round(currentScroll / slideHeight);
        
        if (nextSlideIndex !== activeSlideIndex && nextSlideIndex >= 0 && nextSlideIndex < slideCount) {
            setActiveSlideIndex(nextSlideIndex);
            lastScrollTime.current = Date.now();
        }
    }, [activeSlideIndex, slideCount]);

    const scrollToSlide = (index: number) => {
        if (index >= 0 && index < slideCount) {
            slideRefs.current[index].current?.scrollIntoView({
                behavior: 'smooth',
                block: 'start',
            });
            setActiveSlideIndex(index);
        }
    };

    const goToNextSlide = () => {
        if (activeSlideIndex < slideCount - 1) {
            scrollToSlide(activeSlideIndex + 1);
        }
    };

    const goToPreviousSlide = () => {
        if (activeSlideIndex > 0) {
            scrollToSlide(activeSlideIndex - 1);
        }
    };

    const handleWheel = (event: WheelEvent<HTMLDivElement>) => {
        if (Date.now() - lastScrollTime.current < 500) return;
        
        if (event.deltaY > 0) {
            goToNextSlide();
        } else {
            goToPreviousSlide();
        }
    };

    return (
        <div className="carousel-wrapper">
            <div 
                onScroll={handleScroll} 
                onWheel={handleWheel}
                className='carousel-container'
            >
                {slides.map((Slide, index) => (
                    <div 
                        key={index} 
                        className="carousel-slide" 
                        ref={slideRefs.current[index]}
                        aria-hidden={Math.abs(activeSlideIndex - index) > 1}
                    >
                        <Slide />
                    </div>
                ))}
            </div>
            <CarouselArrow 
                name='Previous' 
                onClickFN={goToPreviousSlide} 
                direction='up' 
                render={activeSlideIndex !== 0} 
            />
            <CarouselArrow 
                name='Next' 
                onClickFN={goToNextSlide} 
                direction='down' 
                render={activeSlideIndex !== slideCount - 1} 
            />
            <CarouselIndex 
                slideCount={slideCount} 
                activeSlideIndex={activeSlideIndex} 
                setSlideFN={scrollToSlide} 
            />
        </div>
    );
};

export default VerticalCarousel;