import React, { useState } from 'react'
import CSS from 'csstype';
import arrow_right from '../assets/svg/right-arrow.svg'

function pointingArrowRotation(direction: string): number {
    switch (direction) {
        case 'right': return 0;
        case 'left': return 180;
        case 'up': return 270;
        case 'down': return 90;
        default: return 0;
    }
}

function pointingArrowPosition(direction: string): CSS.Properties {
    const baseStyle: CSS.Properties = {
        position: 'fixed',
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 2001
    };

    switch (direction) {
        case 'up':
            return { ...baseStyle, top: 'calc(var(--navbar-height) + 20px)' };
        case 'down':
            return { ...baseStyle, bottom: '20px' };
        case 'left':
            return { ...baseStyle, left: '20px', top: '50%', transform: 'translateY(-50%)' };
        case 'right':
            return { ...baseStyle, right: '20px', left: 'auto', top: '50%', transform: 'translateY(-50%)' };
        default:
            return baseStyle;
    }
}

interface ArrowProps {
    name: string;
    onClickFN: () => void;
    direction?: string;
    render?: boolean;
}

const CarouselArrow: React.FC<ArrowProps> = ({
    name,
    onClickFN,
    direction = '',
    render = true
}: ArrowProps) => {
    const [degrees] = useState(pointingArrowRotation(direction));
    const [position] = useState(pointingArrowPosition(direction));

    if (!render) return null;

    return (
        <button
            className="carousel-arrow"
            style={position}
            onClick={onClickFN}
            id={name}
            aria-label={name}
        >
            <img
                src={arrow_right}
                className="carousel-arrow-style"
                style={{ transform: `rotate(${degrees}deg)` }}
                alt={name}
            />
        </button>
    );
};

export default CarouselArrow;