import React, { useMemo } from 'react';

interface IndexButtonProps {
    index: number;
    isActive: boolean;
    setSlideFN: (index: number) => void;
}

const IndexButton: React.FC<IndexButtonProps> = ({ index, isActive, setSlideFN }) => {
    const opacity = { opacity: isActive ? 1 : 0 };
    const buttonClass = `carousel-index-donut ${isActive ? 'carousel-current-index-donut' : ''}`;
    
    return (
        <button 
            key={index} 
            className={buttonClass} 
            onClick={() => !isActive && setSlideFN(index)}
            aria-label={`Go to slide ${index + 1}`}
            aria-current={isActive}
        >
            <div style={opacity} className='carousel-current-index-donut-mark'/>
        </button>
    );
};

interface CarouselIndexProps {
    slideCount: number;
    activeSlideIndex: number;
    setSlideFN: (index: number) => void;
}

const CarouselIndex: React.FC<CarouselIndexProps> = ({ 
    slideCount, 
    activeSlideIndex, 
    setSlideFN 
}) => {
    const slideIndices = useMemo(() => Array.from({ length: slideCount }, (_, i) => i), [slideCount]);

    return (
        <section className='carousel-index' role="navigation" aria-label="Slide navigation">
            <div className='carousel-index-line'/>
            {slideIndices.map(index => (
                <IndexButton 
                    key={index}
                    index={index} 
                    isActive={index === activeSlideIndex} 
                    setSlideFN={setSlideFN}
                />
            ))}
            <div className='carousel-index-line'/>
        </section>
    );
};

export default CarouselIndex;